#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Int8,
    Int16,
    Int32,
    Int64,
    Float16,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

pub fn min_scalar_type(value: i8) -> NumpyDType {
    // All available types have at least 8 bits.
    // At 8 bits, the candidates are UInt8 (kind_order = 0) and Int8 (kind_order = 1).
    // UInt8 can represent 0..=255, Int8 can represent -128..=127.
    // If the value is non‐negative, both UInt8 and Int8 can represent it,
    // so we choose UInt8 because it has smaller kind order.
    // If the value is negative, only Int8 can represent it.
    if value >= 0 {
        NumpyDType::UInt8
    } else {
        NumpyDType::Int8
    }
}

